export const runScenario = ({
  customer,
  steps,
}: Scenario): ScenarioResults => {
  // A claim's `policy` is an ordinal over QUOTE steps, not over all steps, so
  // policies are keyed by how many quotes came before them. That count is also
  // exactly the customer's prior-contract count, so one number serves both.
  const policies: Policy[] = [];

  const results = steps.map((step) => {
    if (isClaimStep(step)) {
      return claim(step, policies[step.policy]!);
    }
    const priorContracts = policies.length;
    policies.push(openPolicy(step.items));
    return quote(step, { customer, priorContracts });
  });

  return { results };
};

